        function statusSlug(status) {
  
            return status.toLowerCase().replace(/[^a-z0-9]+/g, '-')

        }


        function buildDownloadUrl(content) {
  
            return URL.createObjectURL(new Blob([content], { type: 'text/markdown'     }))

        }


        function renderSparkBars(progress) {
  
            const levels = [18, 32, 46, 58, 72, 84, 96]

  
            return levels
    
            .map(level => `<span style="height: ${Math.min(100, Math.max(28, progress >= level ? level : level - 24))}%"></span>`)
    
            .join('')

        }
